CREATE TABLE `secrets` (`type` text NOT NULL,`secret` blob NOT NULL);
CREATE TABLE `mfg_keys` (`type` integer NOT NULL,`pkcs8` blob NOT NULL,`rsa_bits` integer,`x509_chain` blob NOT NULL,PRIMARY KEY (`type`,`rsa_bits`));
CREATE TABLE `owner_keys` (`type` integer NOT NULL,`pkcs8` blob NOT NULL,`rsa_bits` integer,`x509_chain` blob,PRIMARY KEY (`type`,`rsa_bits`));
CREATE TABLE `rv_blobs` (`guid` blob,`rv` blob NOT NULL,`voucher` blob NOT NULL,`exp` datetime NOT NULL,PRIMARY KEY (`guid`));
CREATE INDEX `idx_rv_blob_exp` ON `rv_blobs`(`exp`);
CREATE TABLE `sessions` (`id` blob,`protocol` integer NOT NULL,PRIMARY KEY (`id`));
CREATE TABLE `device_info` (`session` blob,`key_type` integer,`key_encoding` integer,`serial_number` text,`info_string` text,`csr` blob,`x509_chain` blob NOT NULL);
CREATE INDEX `idx_device_info_session` ON `device_info`(`session`);
CREATE TABLE `incomplete_vouchers` (`session` blob,`header` blob NOT NULL,PRIMARY KEY (`session`));
CREATE TABLE `to0_sessions` (`session` blob,`nonce` blob,PRIMARY KEY (`session`));
CREATE TABLE `to1_sessions` (`session` blob,`nonce` blob,`alg` integer,PRIMARY KEY (`session`));
CREATE TABLE `to2_sessions` (`session` blob,`guid` blob,`rv_info` blob,`prove_device` blob,`setup_device` blob,`mtu` integer,`devmod` blob,`modules` blob,`devmod_complete` boolean,PRIMARY KEY (`session`));
CREATE TABLE `vouchers` (`guid` blob,`cbor` blob,`device_info` text,`created_at` datetime,`updated_at` datetime,PRIMARY KEY (`guid`));
CREATE TABLE `replacement_vouchers` (`session` blob,`guid` blob,`hmac` blob,PRIMARY KEY (`session`));
CREATE TABLE `key_exchanges` (`session` blob,`suite` text NOT NULL,`cbor` blob NOT NULL,PRIMARY KEY (`session`));
CREATE TABLE `owner_info` (`id` integer PRIMARY KEY AUTOINCREMENT,`value` text NOT NULL,CONSTRAINT `chk_owner_info_id` CHECK (id = 1));
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE `rvinfo` (`id` integer PRIMARY KEY AUTOINCREMENT,`value` text NOT NULL,CONSTRAINT `chk_rvinfo_id` CHECK (id = 1));
CREATE TABLE `device_onboarding` (`guid` blob,`new_guid` blob,`to2_completed` boolean NOT NULL DEFAULT false,`to2_completed_at` datetime,PRIMARY KEY (`guid`));
CREATE INDEX `idx_device_onboarding_new_guid` ON `device_onboarding`(`new_guid`);
